import osimport jsonimport argparseimport pandas as pdfrom analisis import limpieza, exploracion, embeddings, atipicos, sentimiento, temas, comparacion, precio, imagen, oportunidadesdef conteo(df, fuente):    for f, n in df[fuente].value_counts().items():        print(f"  {f}: {n:,}")def ejecutar(entrada, texto, fuente, dmo, idioma, titulo, paleta, calificacion=None, salida="salidas"):    os.makedirs(salida, exist_ok=True)    df = pd.read_csv(entrada)    print(f"Base cargada: {len(df):,} textos")    for col in [texto, fuente] + ([calificacion] if calificacion else []):        if col not in df.columns:            raise ValueError(f"No existe la columna '{col}'")    if dmo not in df[fuente].unique():        raise ValueError(f"No hay textos de la DMO '{dmo}'")    if df[fuente].nunique() < 2:        raise ValueError("Falta al menos una fuente además de la DMO")    conteo(df, fuente)    df = limpieza.limpiar(df, texto, fuente, idioma, salida)    print(f"Limpieza: {len(df):,} textos válidos")    conteo(df, fuente)    exploracion.explorar(df, texto, fuente, dmo, paleta, salida)    print("Exploración: n-gramas y nubes de palabras")    emb = embeddings.calcular(df, salida)    print(f"Embeddings: {emb.shape[0]:,} textos × {emb.shape[1]} dimensiones")    df = atipicos.analizar(df, emb, fuente, dmo, calificacion, salida)    emb = emb[df["usar"].values]    df = df[df["usar"]].reset_index(drop=True)    print(f"Sin atípicos: {len(df):,} textos")    conteo(df, fuente)    df, sent = sentimiento.calcular(df, fuente, dmo, calificacion, paleta, salida)    print("Sentimiento (% negativo):")    for f, v in sent["negativo"].items():        print(f"  {f}: {v:.1f}%")    df, res = temas.calcular(df, fuente, dmo, paleta, salida)    for g, n in res.groupby("grupo").size().items():        print(f"Temas {g}: {n}")    al, br = comparacion.comparar(df, emb, fuente, dmo, paleta, salida)    print("Alineación con la DMO:")    for r in al.itertuples():        print(f"  {r.fuente}: {r.alineacion:.2f}")    df, pr = precio.analizar(df, fuente, dmo, paleta, salida)    print("Hablan de precio:")    for r in pr.itertuples():        print(f"  {r.fuente}: {r.pct_precio:.1f}% ({r.pct_negativo_precio:.0f}% negativo)")    img = imagen.imagen(df, fuente, dmo, paleta, salida)    print("Imagen global (tema principal de visitantes):")    for g, p in img.items():        print(f"  {g}: {p.index[0]} ({p['visitantes'].iloc[0]:.0f}%)")    op = oportunidades.generar(br, img, pr, al, dmo, salida)    print(f"Áreas de oportunidad: {len(op)}")    config = {"titulo": titulo, "paleta": paleta, "dmo": dmo, "idioma": idioma,              "fuente": fuente, "texto": texto, "calificacion": calificacion,              "fecha": pd.Timestamp.today().strftime("%d/%m/%Y")}    with open(f"{salida}/config.json", "w", encoding="utf-8") as f:        json.dump(config, f, ensure_ascii=False, indent=2)    print(f"Listo. Resultados en '{salida}/'")if __name__ == "__main__":    p = argparse.ArgumentParser(description="Imagen proyectada (DMO) vs. imagen percibida")    p.add_argument("-i", "--entrada", required=True, help="CSV unificado")    p.add_argument("-c", "--texto", required=True, help="columna de los comentarios")    p.add_argument("-f", "--fuente", required=True, help="columna de la fuente")    p.add_argument("-d", "--dmo", required=True, help="etiqueta de la DMO en la columna fuente")    p.add_argument("-l", "--idioma", required=True, help="idioma del análisis: es, en, ...")    p.add_argument("-t", "--titulo", required=True, help="título del reporte")    p.add_argument("-p", "--paleta", required=True,                   choices=["viridis", "cividis", "plasma", "inferno"], help="paleta de colores")    p.add_argument("--calificacion", default=None, help="columna de estrellas (opcional)")    p.add_argument("-o", "--salida", default="salidas", help="carpeta de resultados (opcional)")    a = p.parse_args()    ejecutar(a.entrada, a.texto, a.fuente, a.dmo, a.idioma, a.titulo, a.paleta, a.calificacion, a.salida)